export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "17:50。臨時指揮室。白板上的字跡乾了。上一場的排程和控制措施還留在上面。指定專家在旁邊的桌上攤開另一疊文件。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "這一疊不是排程。是版本治理鏈。R1。R2。R3。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "R1 和 R2 已經在上午建立。父親的安全原則。千田的技術附錄。現在——R3。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "KAGAMI-SAFE／R3。紗英臨床安全修訂。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻開一份文件。不是完整正文。是索引頁。文件名、日期、轉錄者、雜湊。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "R3 的正文仍不完整。當輪可見的只有——文件索引與雜湊、R1 的三段引用、一張臨床實施檢查表，以及紗英的當輪確認。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯又是碎片。不是完整文件。是索引、引用、檢查表。⋯⋯可是碎片也能重建部分原則。⋯⋯夠不夠——不知道。先看。", background: Background.Chapter_21_Ch21_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "R1 引用 R3 的三個摘要。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他在白板空出來的角落寫了三行。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "第一。完整未成立未來方案會增加來源混淆。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "第二。每輪必須重新驗證。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "第三。託管回聲只應攜帶必要安全錨點。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "這三句是父親寫的？", background: Background.Chapter_21_Ch21_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "是 R1 正文引用 R3 的摘要。父親在 R1 中引用了紗英較早期的臨床安全紀錄。引用本身有 R1 的文件雜湊可以驗證。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著那三行。每一句都很短。像被壓縮過的安全指令。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯完整未成立未來方案會增加來源混淆。⋯⋯每輪必須重新驗證。⋯⋯託管回聲只應攜帶必要安全錨點。⋯⋯這三句不是在說「不要記得」。是在說「不要把還沒確定的東西完整塞回去」。⋯⋯區分。她在區分什麼可以送回、什麼不能。", background: Background.Chapter_21_Ch21_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "臨床實施檢查表。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到另一頁。一張表格。欄位很少。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "可見欄位——LOCATION。TIME。PERSON。REFUSE。FULL PACKAGE：禁止。ESCROW：最低必要。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "六個欄位。兩個結論。禁止完整套件。託管只留最低必要。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "REFUSE 是什麼？", background: Background.Chapter_21_Ch21_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "依上下文推斷——接收者有權拒絕。但具體拒絕機制在正文缺失部分。無法從檢查表單獨重建。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "PERSON 是誰？", background: Background.Chapter_21_Ch21_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "不確定。可能是接收者、可能是授權者、可能是轉錄者。正文缺失。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:10。外部醫師走進來。他在旁邊的平板上確認了什麼。然後對日下部點頭。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "紗英可以進行低負荷確認。極短。不超過幾分鐘。", background: Background.Chapter_21_Ch21_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部看著澪。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不是測試。是確認。讓她看見 R3 的可見摘要，確認或修正。不提供 R4 選項。不提示版本編號。", background: Background.Chapter_21_Ch21_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我明白。", background: Background.Chapter_21_Ch21_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:15。M-00 醫療區。澪站在觀察窗外。日下部在裡面。外部醫師在旁邊監測。呼吸治療師確認發聲閥參數。", background: Background.Chapter_21_Ch21_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英的眼睛半開著。和凌晨一樣。呼吸迴路的聲音很慢。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部把一張紙放在紗英視線範圍內。紙上只有 R3 的可見摘要——三句引用、檢查表欄位。沒有版本編號。沒有 R4。沒有任何快捷選項。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "呼吸治療師接上發聲閥。氣流的節奏變了。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "這份摘要——針對的是什麼？", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英的眼球動了。很慢。從左到右。像在讀。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯額外。", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.AsakuraSae_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "一個詞。很乾。像被擠過很窄的管道。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "額外什麼？", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯託管。", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.AsakuraSae_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師看著監測器。血氧九十三。呼吸頻率十九。在範圍內。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "R3 限制的是額外託管回聲。不是上一輪的生活記憶。對嗎？", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯對。", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.AsakuraSae_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "完整未成立未來方案——不得直接託管送回？", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯不得。", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.AsakuraSae_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "三個確認。額外託管。不限制生活記憶。完整未來方案不得送回。每一個都只用了最少的字。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "呼吸治療師看著監測器。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.RespiratoryTherapist, character: "呼吸治療師", dialogue: "血氧九十一。趨勢下降。建議中止。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "中止。", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "發聲閥被切換。封閉模式。嘶嘶聲回來了。紗英的眼睛閉上了。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:28。確認結束。總時長不到四分鐘。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部走出醫療區。他看著澪。", background: Background.Chapter_21_Ch21_Act6_S1 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "三個確認。R3 針對額外託管回聲。不限制七日經歷回送。完整未成立未來方案不得直接託管送回。", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯兩條通道。⋯⋯一條是七日經歷回送。我記得自己剛生活過的七天。相對完整。有人物、對話、文件、連續敘事。R3 不限制這條。⋯⋯另一條是額外記憶託管回聲。來源不是上一輪。是下一個回聲窗可涵蓋的未來。只留下安全錨點。不能把完整答案塞回來。⋯⋯這解釋了——為什麼我完整記得第一輪和第二輪。也解釋了——為什麼我對某些還沒生活過的東西有模糊熟悉。", background: Background.Chapter_21_Ch21_Act6_S1, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "回到指揮室。18:35。指定專家在白板上畫了兩條線。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "正式區分。兩種記憶通道。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他在第一條線上方寫：", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "A。七日經歷回送。白光後，接收者保留自己剛生活過的七日。相對完整。有人物、對話、文件與連續敘事。第一輪與第二輪均屬此類。R3 不限制。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他在第二條線上方寫：", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "B。額外記憶託管回聲。來源只能落在七日回聲規則可涵蓋的未來範圍。可能來自更晚但尚未成立的星期一回聲窗。不屬於接收者剛生活過的上一輪。以詞、圖像、身體感、地點、時間及選擇壓力出現。R3 限制——不得把完整未成立未來方案託管送回。只可留下安全錨點。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯七日經歷回送——是我的記憶。我走過的路。我自己的七天。⋯⋯額外託管回聲——不是我的記憶。是某條未來送回來的碎片。⋯⋯R3 只管第二條。不管第一條。⋯⋯這不是「不要記得」。是「不要把未來的答案完整塞回現在」。", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "可能屬於額外託管回聲的——有哪些？", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "依 R3 原則和當輪證據——只限於：對黑色海的超前熟悉與恐懼。對 06:13 的身體性反應。對最短、最快方案的排斥壓力。對鏡島位置的一瞬熟悉。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "不歸入託管回聲的——七秒的精確數值、TOKYO-7 名稱、G07／12、鏡背刻痕、「不要救東京」完整句。這些仍由千田、悠真、文件及當輪調查建立。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯分開了。⋯⋯情緒和身體感——可能是託管的。⋯⋯精確線索——是當輪調查的。⋯⋯不能把所有東西都歸因於未來提示。也不能假裝那些模糊熟悉不存在。", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:50。日下部在筆記本上寫了什麼。然後抬頭。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "下一個回聲窗。", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著白板上的時間線。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "R4 如果存在——它的時間來源被綁定為什麼？", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "依 R3 原則推論——額外託管回聲必須服從七日規則。來源必須在某個星期一 06:13 前形成，並由該次白光向前回送七日。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "如果 R4 存在——它的時間錨是下一個星期一 06:13。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他在白板上畫了一個簡單的圖。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "```text 本週星期一 06:13         ↑ 七日回聲 下一個星期一 06:13 前完成的可能未來 R4 ```", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "R4 不來自已經發生的第一輪、第二輪或隱藏既往輪次。它只能來自當前第三輪繼續向前、在下一個星期一 06:13 前完成、並由該次白光把託管回聲送回本週星期一 06:13 的可能未來。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯下一個星期一。⋯⋯不是過去。是未來。⋯⋯R4 不是隱藏的第四輪。是一條還沒發生的可能未來。⋯⋯如果它存在——它來自我還沒走到的下一個七天。", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "當前距離下一個星期一 06:13——", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看了一眼手機。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "約四天十二小時二十三分。從 17:50 起算。", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著白板上的圖。兩個星期一。一個箭頭。一個回聲窗。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯四天十二小時。⋯⋯在那段時間裡，某條可能未來中的我——會寫出 R4 嗎？⋯⋯如果會——那條未來的回聲已經送回來了。⋯⋯如果改變了——那條未來可能不再發生。⋯⋯可是痕跡已經在。在媽媽的記憶裡。在我的身體裡。", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "19:05。指定專家合上文件。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "R3 正文仍不完整。當輪可見——索引、雜湊、R1 三段引用、臨床實施檢查表、紗英確認。不能重建的部分——具體神經參數、如何選擇錨點、哪些人可接收、是否曾實際執行、R4 如何被託管、紗英能否主動選擇未來分支。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "這些留待後續。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯又不完整。⋯⋯R1 有五項原則但父親下落不明。R2 有技術邊界但七秒不能取代 COMMIT-GATE。R3 有三句引用和一張檢查表但正文缺失。⋯⋯三個版本。三個碎片。⋯⋯可是碎片有方向。⋯⋯父親說先撤離再切離。千田說分段隔離不是硬切。紗英說只留錨點不要塞完整答案。⋯⋯三個人在說同一件事的不同部分。⋯⋯他們從來沒有同桌制定計畫。可是版本鏈把他們連在一起。", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "19:15。指揮室。白板上寫滿了。兩種記憶通道。R3 的三句引用。檢查表的六個欄位。紗英的三個確認。下一回聲窗的時間錨。不能重建的六個空白。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪合上筆記本。她的手在發抖。不是冷。是某種被太多碎片同時壓著的重量。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯兩條通道。⋯⋯一條是我的。一條是未來送回來的。⋯⋯R3 只管第二條。⋯⋯R4 如果存在——它在第二條裡。⋯⋯而第二條的作者——⋯⋯不知道。還不知道。", background: Background.Chapter_21_Ch21_Act6_S2, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "19:20。指揮室。螢光燈的嗡聲很穩。白板上的字跡已經乾透了。", background: Background.Chapter_21_Ch21_Act6_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約四日十小時五十三分鐘。", background: Background.Chapter_21_Ch21_Act6_S2 },
];
